import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

/** Java 21 worker restriction policy; never used to change the parent VM. */
@SuppressWarnings("removal")
final class IsolatedJavaExtension {
    static List<ReaExtension.Issue> run(Path jar,String method,String url,byte[] request,byte[] response)throws Exception{Path folder=Files.createTempDirectory("vuln-java-extension-");Path input=folder.resolve("input"),output=folder.resolve("output"),error=folder.resolve("error");try{Files.writeString(input,Json.write(Map.of("jar",jar.toAbsolutePath().toString(),"method",method,"url",url,"request",Base64.getEncoder().encodeToString(request),"response",Base64.getEncoder().encodeToString(response))));String java=Path.of(System.getProperty("java.home"),"bin","java.exe").toString();Process process=new ProcessBuilder(java,"-Djava.security.manager=allow","-Xmx96m","-XX:MaxMetaspaceSize=64m","-cp",System.getProperty("java.class.path"),"IsolatedJavaExtension",input.toString()).redirectOutput(output.toFile()).redirectError(error.toFile()).start();if(!process.waitFor(5,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor(2,TimeUnit.SECONDS);throw new IOException("Extension exceeded time limit");}if(process.exitValue()!=0)throw new IOException("Isolated extension failed; file/network/process access may have been denied");if(Files.size(output)>1024*1024)throw new IOException("Extension output limit");List<ReaExtension.Issue> issues=new ArrayList<>();for(Object item:(List<?>)Json.parse(Files.readString(output))){Map<String,Object> row=Json.object(item);issues.add(new ReaExtension.Issue(row.get("severity").toString(),row.get("title").toString(),row.get("evidence").toString()));if(issues.size()>100)throw new IOException("Extension finding limit");}return issues;}finally{for(Path p:List.of(input,output,error))Files.deleteIfExists(p);Files.deleteIfExists(folder);}}
    public static void main(String[] args)throws Exception{Map<String,Object> input=Json.object(Json.parse(Files.readString(Path.of(args[0]))));Path jar=Path.of(input.get("jar").toString()).toAbsolutePath();byte[] request=Base64.getDecoder().decode(input.get("request").toString()),response=Base64.getDecoder().decode(input.get("response").toString());String method=input.get("method").toString(),url=input.get("url").toString();List<Path> reads=new ArrayList<>();reads.add(jar);for(String part:System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(File.pathSeparator)))reads.add(Path.of(part).toAbsolutePath().normalize());Path runtime=Path.of(System.getProperty("java.home")).toAbsolutePath().normalize();
        SecurityManager guard=new SecurityManager(){public void checkPermission(Permission permission){String name=permission.getName();if(permission instanceof FilePermission file){if(file.getActions().equals("read")){Path path=Path.of(name).toAbsolutePath().normalize();if(path.startsWith(runtime)||reads.stream().anyMatch(p->path.equals(p)||(Files.isDirectory(p)&&path.startsWith(p))))return;}throw new SecurityException("File access denied");}if(permission instanceof java.util.PropertyPermission property&&property.getActions().equals("read"))return;if(permission instanceof RuntimePermission&&Set.of("createClassLoader","getClassLoader","accessDeclaredMembers","accessSystemModules","charsetProvider").contains(name))return;if(permission instanceof SecurityPermission&&name.startsWith("getProperty."))return;throw new SecurityException("Denied: "+permission);}};
        // Warm up parent classes before enabling the worker-only policy.
        Class.forName("ReaExtension$Issue");Class.forName("VulnExtension$Issue");Json.write(Map.of());
        System.setSecurityManager(guard);List<Object> result=new ArrayList<>();try(URLClassLoader loader=new URLClassLoader(new URL[]{jar.toUri().toURL()},VulnExtension.class.getClassLoader())){for(VulnExtension provider:ServiceLoader.load(VulnExtension.class,loader)){var found=provider.inspect(method,url,request.clone(),response.clone());if(found!=null)for(var issue:found)result.add(Map.of("severity",issue.severity(),"title",issue.title(),"evidence",issue.evidence()));}for(ReaExtension provider:ServiceLoader.load(ReaExtension.class,loader)){var found=provider.inspect(method,url,request.clone(),response.clone());if(found!=null)for(var issue:found)result.add(Map.of("severity",issue.severity(),"title",issue.title(),"evidence",issue.evidence()));}System.out.print(Json.write(result));}}
}
